                    Entities myentity = currEntities.FirstOrDefault(a => a.Id.ToString().ToLower() == field.EntityId.ToLower());
                    if (myentity == null)
                    {
                        myentity = _context.Entities.FirstOrDefault(a => a.Id.ToString() == field.EntityId);
                        if (tables != "")
                            tables += ",";
                        tables += "[dbo].[" + myentity.SysName + "]";
                        currEntities.Add(myentity);
                    }

                    object value = Row[myfield.DisplayName];
                    if (myfield.SystemName != "Id")
                    {

                        int pcount = parameters.Count + 1;
                        if (values != "")
                        {
                            values += ",";
                        }
                        if (columns != "")
                        {
                            columns += ",";
                        }
                        columns +="[dbo].[" + myentity.SysName + "].[" + myfield.SystemName + "]";
                        values += " @p" + pcount;
                        SqlParameter param = CreateParameterByType(myfield, value, pcount);
                        parameters.Add(param);

                    }

                }
                if (values != "")
                    values = " VALUES ( " + values+")";
                if (columns != "")
                    columns = " ( " + columns+") ";
                if (tables != "")
                    tables = " INSERT INTO " + tables;
                if (values != "" && tables != "" && values != "")
                {
                    string sql = tables + columns + values ;
                    return database.Execute(sql, parameters.ToArray());

                }

            }


        }
    }
    return status;
}

